import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Releases — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"releases-02-how-tos-and-workflows.md","filePath":"releases-02-how-tos-and-workflows.md"}'),s={name:"releases-02-how-tos-and-workflows.md"};function n(i,e,l,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="releases-—-how-tos-workflows" tabindex="-1">Releases — How-tos &amp; Workflows <a class="header-anchor" href="#releases-—-how-tos-workflows" aria-label="Permalink to &quot;Releases — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for the most common Release workflows</em></p><hr><h2 id="creating-a-release" tabindex="-1">Creating a Release <a class="header-anchor" href="#creating-a-release" aria-label="Permalink to &quot;Creating a Release&quot;">​</a></h2><p>Any workspace member can create a Release. There are two starting points.</p><h3 id="option-a-create-a-blank-release" tabindex="-1">Option A: Create a blank Release <a class="header-anchor" href="#option-a-create-a-blank-release" aria-label="Permalink to &quot;Option A: Create a blank Release&quot;">​</a></h3><ol><li>Navigate to the Releases module from the left-hand navigation.</li><li>Create a new Release and give it a name. Names can be changed at any time.</li><li>A Kanban board is created with your default status stages.</li><li>Add Features from your backlog using the Feature dropdown.</li></ol><h3 id="option-b-create-from-a-roadmap" tabindex="-1">Option B: Create from a Roadmap <a class="header-anchor" href="#option-b-create-from-a-roadmap" aria-label="Permalink to &quot;Option B: Create from a Roadmap&quot;">​</a></h3><ol><li>Navigate to the Releases module.</li><li>Choose the option to create from an existing Roadmap.</li><li>Select the Roadmap. All Features from that Roadmap are automatically added to the Release.</li><li>Give the Release a name.</li></ol><p>Creating from a Roadmap is the most common pattern for quarterly or milestone-based tracking — it ensures your Release reflects your planned work without having to add Features one by one.</p><hr><h2 id="adding-and-removing-features" tabindex="-1">Adding and Removing Features <a class="header-anchor" href="#adding-and-removing-features" aria-label="Permalink to &quot;Adding and Removing Features&quot;">​</a></h2><h3 id="adding-features" tabindex="-1">Adding Features <a class="header-anchor" href="#adding-features" aria-label="Permalink to &quot;Adding Features&quot;">​</a></h3><p>Use the Feature dropdown on the Release board to select Features from your backlog. Features appear as cards in the column matching their current status.</p><h3 id="removing-features" tabindex="-1">Removing Features <a class="header-anchor" href="#removing-features" aria-label="Permalink to &quot;Removing Features&quot;">​</a></h3><p>To remove a Feature from a Release, use the remove option on the Feature card. Removing a Feature from a Release does not affect the Feature itself — it remains in the backlog and any other Releases it belongs to.</p><hr><h2 id="updating-feature-status" tabindex="-1">Updating Feature Status <a class="header-anchor" href="#updating-feature-status" aria-label="Permalink to &quot;Updating Feature Status&quot;">​</a></h2><p>Feature status can be updated directly from the Release board by dragging a card to a different column. This updates the Feature&#39;s status everywhere — in the backlog, in other Releases, and in any other view.</p><blockquote><p><strong>Important:</strong> Because status is a single source of truth, a status change here is a real change. If your team uses JIRA and has the integration active, status changes in JIRA will also flow through to your Release board automatically.</p></blockquote><hr><h2 id="using-forecast-mode" tabindex="-1">Using Forecast Mode <a class="header-anchor" href="#using-forecast-mode" aria-label="Permalink to &quot;Using Forecast Mode&quot;">​</a></h2><p>Forecast mode lets you project anticipated progress without changing real status data.</p><ol><li>Toggle the Release to <strong>Forecast</strong> mode using the Actual / Forecast toggle.</li><li>Move Feature cards to the columns representing their anticipated status.</li><li>Export the forecast view as a PNG or PPT to share with stakeholders.</li></ol><p>Forecast changes are saved separately from actual status and persist until you manually clear them. Toggling back to Actual shows the real state — your forecast positions are preserved for when you return to Forecast mode.</p><blockquote><p><strong>Use case:</strong> Before a stakeholder check-in, switch to Forecast, move Features to reflect what you expect to be completed by the meeting date, and export that view to share as a &quot;projected status&quot; snapshot.</p></blockquote><hr><h2 id="generating-release-notes" tabindex="-1">Generating Release Notes <a class="header-anchor" href="#generating-release-notes" aria-label="Permalink to &quot;Generating Release Notes&quot;">​</a></h2><p>Release Notes are generated from within the Release and can be tailored to different audiences.</p><ol><li>Open the Release.</li><li>Navigate to the Release Notes section.</li><li>Select the Features you want to include from the board.</li><li>Choose your audience: <ul><li><strong>Internal</strong> — suitable for team members, leadership, and CS</li><li><strong>External</strong> — suitable for customers and partners</li></ul></li><li>Generate. Lodestone produces a text-based set of notes tailored to the chosen audience.</li></ol><p>Release Notes can be:</p><ul><li><strong>Exported as a PDF</strong> for distribution</li><li><strong>Copied</strong> directly for use in email, Slack, or other channels</li></ul><blockquote><p><strong>Note:</strong> Regenerating Release Notes overwrites the previous version. If you need to preserve a previous version, copy or export it before regenerating.</p></blockquote><hr><h2 id="creating-multiple-sets-of-release-notes" tabindex="-1">Creating Multiple Sets of Release Notes <a class="header-anchor" href="#creating-multiple-sets-of-release-notes" aria-label="Permalink to &quot;Creating Multiple Sets of Release Notes&quot;">​</a></h2><p>A single Release can have multiple sets of Release Notes — for example, one for an internal audience and one for customers.</p><p>Generate internal notes first, export or copy them, then generate again with the External audience setting to produce the external version.</p><hr><h2 id="exporting-a-release" tabindex="-1">Exporting a Release <a class="header-anchor" href="#exporting-a-release" aria-label="Permalink to &quot;Exporting a Release&quot;">​</a></h2><p>Releases can be exported in three formats:</p><h3 id="png" tabindex="-1">PNG <a class="header-anchor" href="#png" aria-label="Permalink to &quot;PNG&quot;">​</a></h3><p>A static image of the Kanban board in its current state. Useful for quick sharing in emails, Slack, or documents.</p><h3 id="ppt" tabindex="-1">PPT <a class="header-anchor" href="#ppt" aria-label="Permalink to &quot;PPT&quot;">​</a></h3><p>A PowerPoint version of the board. Useful when incorporating the Release view into a larger presentation.</p><h3 id="markdown-md" tabindex="-1">Markdown (.md) <a class="header-anchor" href="#markdown-md" aria-label="Permalink to &quot;Markdown (.md)&quot;">​</a></h3><p>A text-based export of the Release, formatted as a Markdown document. Useful for pasting into Notion, Confluence, GitHub, or any tool that accepts Markdown.</p><h3 id="html-shareable-link" tabindex="-1">HTML (shareable link) <a class="header-anchor" href="#html-shareable-link" aria-label="Permalink to &quot;HTML (shareable link)&quot;">​</a></h3><p>Generates a responsive, server-rendered HTML snapshot of your Release board and returns a shareable link. Like Roadmap HTML exports, this produces a <code>/share/...</code> URL rather than downloading a file — anyone with the link can view the Release in a browser without logging in to Lodestone.</p><p>To generate, click the <strong>Export as HTML</strong> button in the Release toolbar. Each generation produces a new URL; previous links remain valid.</p><p>Both the <strong>Actual</strong> and <strong>Forecast</strong> views can be exported — make sure you&#39;re in the correct mode before exporting.</p><blockquote><p><strong>Note:</strong> Release PNG, PPT, and Markdown exports do not include AI-generated text or speaker notes. The export is a clean visual of the board as-is.</p></blockquote><hr><h2 id="renaming-a-release" tabindex="-1">Renaming a Release <a class="header-anchor" href="#renaming-a-release" aria-label="Permalink to &quot;Renaming a Release&quot;">​</a></h2><p>Release names can be edited at any time. Click the Release name to edit it directly.</p><hr><h2 id="archiving-a-release" tabindex="-1">Archiving a Release <a class="header-anchor" href="#archiving-a-release" aria-label="Permalink to &quot;Archiving a Release&quot;">​</a></h2><p>When a Release is complete or no longer active:</p><ol><li>Open the Release settings or options menu.</li><li>Select Archive.</li></ol><p>Archiving removes the Release from your active list but preserves it for reference. All Features in the Release are unaffected — they remain in the backlog and any other Releases they belong to.</p><hr><p><em>Next: Advanced Features &amp; Customization — Forecast mode strategy, Release Notes best practices, and JIRA sync behavior.</em></p>',61)])])}const g=a(s,[["render",n]]);export{p as __pageData,g as default};
